115	where
116	    T: Iterator<Item = (u32, char)>,
117	{
118	    pub fn new(input: T) -> Self {
119	        let mut lxr = Lexer {
120	            chars: input,
121	            pending: Vec::new(),
122	            chr0: None,
123	            chr1: None,
124	            loc0: 0,
125	            loc1: 0,
126	        };
127	        let _ = lxr.next_char();
128	        let _ = lxr.next_char();
129	        lxr
130	    }
