132	    // This is the main entry point. Call this function to retrieve the next token.
133	    // This function is used by the iterator implementation.
134	    fn inner_next(&mut self) -> LexResult {
135	        // top loop, keep on processing, until we have something pending.
136	        while self.pending.is_empty() {
137	            self.consume_normal()?;
138	        }
139	
140	        Ok(self.pending.remove(0))
141	    }
142	
143	    // Take a look at the next character, if any, and decide upon the next steps.
144	    fn consume_normal(&mut self) -> Result<(), LexicalError> {
145	        // Check if we have some character:
146	        if let Some(c) = self.chr0 {
147	            let mut check_for_minus = false;
148	            if self.is_upname_start(c) {
149	                let name = self.lex_upname()?;
150	                self.emit(name)
151	            } else if self.is_name_start(c) {
152	                check_for_minus = true;
153	                let name = self.lex_name()?;
154	                self.emit(name);
155	            } else if self.is_number_start(c, self.chr1) {
156	                check_for_minus = true;
157	                let num = self.lex_number()?;
158	                self.emit(num);
159	            } else {
160	                self.consume_character(c)?;
161	            }
162	            if check_for_minus {
163	                // We want to lex `1-1` and `x-1` as `1 - 1` and `x - 1`
164	                if Some('-') == self.chr0 && self.is_number_start('-', self.chr1) {
165	                    self.eat_single_char(Token::Minus);
166	                }
167	            }
168	        } else {
169	            // We reached end of file.
170	            let tok_pos = self.get_pos();
171	            self.emit((tok_pos, Token::EndOfFile, tok_pos));
172	        }
173	
174	        Ok(())
175	    }
