177	    fn consume_character(&mut self, c: char) -> Result<(), LexicalError> {
178	        match c {
179	            '@' => {
180	                self.eat_single_char(Token::At);
181	            }
182	            '"' => {
183	                let string = self.lex_string()?;
184	                self.emit(string);
185	            }
186	            '=' => {
